examples.template:
Row(verticalAlignment = Alignment.CenterVertically) {
    MonarchText(text = if (deleted) {{rowLabel}} + " (deleted)" else {{rowLabel}}, modifier = Modifier.weight(1f))
    Box {
        MonarchIconButton(label = "Actions for " + {{rowLabel}}, onClick = { expanded = true }, size = MonarchButtonSize.Sm) {
            MonarchIcon(SampleIcons.More, contentDescription = null)
        }
        MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
            MonarchMenuItem(text = {{actions.0.label}}, onClick = { expanded = false })
            MonarchMenuItem(text = {{actions.1.label}}, onClick = { expanded = false }, shortcut = {{actions.1.shortcut}})
            MonarchMenuDivider()
            MonarchMenuItem(
                text = {{actions.2.label}},
                onClick = {
                    expanded = false
                    confirming = true
                },
                destructive = {{actions.2.tone}} == "danger",
            )
        }
    }
}
if (confirming) {
    MonarchDialog(
        onDismissRequest = { confirming = false },
        title = {{actions.2.confirm.title}},
        description = {{actions.2.confirm.description}},
        actions = {
            MonarchButton(text = "Cancel", onClick = { confirming = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(
                text = {{actions.2.confirm.confirmLabel}},
                onClick = {
                    deleted = true
                    confirming = false
                },
                variant = MonarchButtonVariant.Danger,
            )
        },
    )
}

