examples.code:
Row(verticalAlignment = Alignment.CenterVertically) {
    MonarchText(text = if (deleted) "Report 12" + " (deleted)" else "Report 12", modifier = Modifier.weight(1f))
    Box {
        MonarchIconButton(label = "Actions for " + "Report 12", onClick = { expanded = true }, size = MonarchButtonSize.Sm) {
            MonarchIcon(SampleIcons.More, contentDescription = null)
        }
        MonarchMenu(expanded = expanded, onDismissRequest = { expanded = false }) {
            MonarchMenuItem(text = "Open", onClick = { expanded = false })
            MonarchMenuItem(text = "Rename", onClick = { expanded = false }, shortcut = "F2")
            MonarchMenuDivider()
            MonarchMenuItem(
                text = "Delete",
                onClick = {
                    expanded = false
                    confirming = true
                },
                destructive = "danger" == "danger",
            )
        }
    }
}
if (confirming) {
    MonarchDialog(
        onDismissRequest = { confirming = false },
        title = "Delete Report 12?",
        description = "The report and its history are removed.",
        actions = {
            MonarchButton(text = "Cancel", onClick = { confirming = false }, variant = MonarchButtonVariant.Ghost)
            MonarchButton(
                text = "Delete report",
                onClick = {
                    deleted = true
                    confirming = false
                },
                variant = MonarchButtonVariant.Danger,
            )
        },
    )
}

Column {
    companies.forEach { company ->
        key(company) {
            val archive = { companies = companies - company }
            SwipeToDismissBox(
                state = rememberSwipeToDismissBoxState(),
                backgroundContent = {
                    Box(
                        modifier = Modifier.fillMaxSize().background(MonarchTheme.colors.warningSubtle),
                        contentAlignment = Alignment.CenterEnd,
                    ) {
                        MonarchText(text = "Archive", color = MonarchTheme.colors.warningStrong)
                    }
                },
                enableDismissFromStartToEnd = false,
                onDismiss = { archive() },
            ) {
                MonarchText(
                    text = company,
                    modifier = Modifier
                        .fillMaxWidth()
                        .background(MonarchTheme.colors.bgSurface)
                        .padding(MonarchTheme.spacing.space4)
                        .semantics {
                            customActions = listOf(
                                CustomAccessibilityAction("Archive") {
                                    archive()
                                    true
                                },
                            )
                        },
                )
            }
        }
    }
}
